WITH cr_daily AS ( SELECT cr_returned_date_sk, SUM(cr_return_amt_inc_tax) AS cr_return_amt_inc_tax FROM catalog_returns GROUP BY cr_returned_date_sk ), wr_daily AS ( SELECT wr_returned_date_sk, SUM(wr_return_amt_inc_tax) AS wr_return_amt_inc_tax FROM web_returns GROUP BY wr_returned_date_sk ), store_daily AS ( SELECT s_closed_date_sk, COUNT(DISTINCT s_store_sk) AS closed_store_cnt FROM store GROUP BY s_closed_date_sk ), daily_returns AS ( SELECT d.d_date, d.d_year, COALESCE(cr_daily.cr_return_amt_inc_tax, 0) + COALESCE(wr_daily.wr_return_amt_inc_tax, 0) AS total_return_amt, COALESCE(store_daily.closed_store_cnt, 0) AS closed_store_cnt FROM date_dim d LEFT JOIN cr_daily ON cr_daily.cr_returned_date_sk = d.d_date_sk LEFT JOIN wr_daily ON wr_daily.wr_returned_date_sk = d.d_date_sk LEFT JOIN store_daily ON store_daily.s_closed_date_sk = d.d_date_sk WHERE d.d_year BETWEEN 2021 AND 2023 ) SELECT * FROM ( SELECT d_date, d_year, total_return_amt, closed_store_cnt, AVG(total_return_amt) OVER (ORDER BY d_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7d, CASE WHEN total_return_amt > AVG(total_return_amt) OVER (ORDER BY d_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) THEN 'Above Avg' ELSE 'Below Avg' END AS performance_flag, ROW_NUMBER() OVER (ORDER BY total_return_amt DESC) AS rn FROM daily_returns ) t WHERE rn <= 5 ORDER BY total_return_amt DESC
